data.default.conf.template:
server {
    listen 8000;

    client_max_body_size 20m;

    # Backend root only
    location = / {
        default_type application/json;
        return 200 '{"service":"AgroMind API","status":"ok"}';
    }

    # Public health check
    location = /health {
        default_type application/json;
        return 200 '{"status":"ok"}';
    }

    # Internal Prometheus metrics
    location = /metrics {
        proxy_pass http://agromind-serving.agromind-h100.svc.cluster.local:8000/metrics;
        proxy_set_header Authorization "";
        proxy_http_version 1.1;
    }

    # Protected model information
    location = /v1/models {
        if ($http_authorization != "Bearer ${API_KEY}") {
            return 401;
        }

        proxy_pass http://agromind-serving.agromind-h100.svc.cluster.local:8000/v1/models;
        proxy_set_header Authorization "";
        proxy_http_version 1.1;
    }

    # Protected inference endpoint
    location = /v1/chat/completions {
        if ($http_authorization != "Bearer ${API_KEY}") {
            return 401;
        }

        proxy_pass http://agromind-serving.agromind-h100.svc.cluster.local:8000/v1/chat/completions;
        proxy_set_header Authorization "";

        proxy_http_version 1.1;
        proxy_connect_timeout 60s;
        proxy_send_timeout 300s;
        proxy_read_timeout 300s;
    }

    # Do not expose anything else
    location / {
        return 404;
    }
}
